namespace Ncw.Protocol.Tests;

/// <summary>
/// 内置模版 DTO 的冻结向量(协议 v1,能力 <c>providers.templates</c> 批次生成;<c>providers.media</c> 追加带默认值的末尾 <c>Kind</c>)。
/// 这些测试失败说明某个 DTO 的键名 / 形状变了,那必须升协议版本或加能力开关,不能直接改向量(见 <see cref="ProviderTemplatesDtoTests"/>)。
/// </summary>
internal static class GoldenV1ProviderTemplates
{
    public const string ListWithoutKind =
        "";

    public const string List =
        "";

    public static string Of(string name) => name switch
    {
        "templates.list" => List,
        _ => throw new ArgumentOutOfRangeException(nameof(name), name, null),
    };
}
